audit_nodes={}
audit_labels={}
audit_nextid=0
def audit_new(kind,ea,expr=None):
 global audit_nextid
 audit_nextid+=1
 node={'id':audit_nextid,'kind':kind,'ea':int(ea),'expr':expr,'next':[]}
 audit_nodes[node['id']]=node
 return node['id']
def audit_expr(e,nxt,ea):
 n=audit_new('expr',ea,e)
 audit_nodes[n]['next']=[nxt]
 return n
def audit_build(ins,nxt,brk=None,cont=None):
 h=ida_hexrays;op=ins.op
 if op==h.cit_block:
  start=nxt
  for child in reversed(list(ins.cblock)):start=audit_build(child,start,brk,cont)
  if ins.label_num>=0:audit_labels[int(ins.label_num)]=start
  return start
 n=audit_new('other',ins.ea)
 d=audit_nodes[n]
 if ins.label_num>=0:audit_labels[int(ins.label_num)]=n
 if op==h.cit_expr:
  d.update(kind='expr',expr=ins.cexpr,next=[nxt])
 elif op==h.cit_if:
  d.update(kind='branch',expr=ins.cif.expr,next=[audit_build(ins.cif.ithen,nxt,brk,cont),audit_build(ins.cif.ielse,nxt,brk,cont) if ins.cif.ielse else nxt])
 elif op in (h.cit_while,h.cit_do):
  part=ins.cwhile if op==h.cit_while else ins.cdo
  body=audit_build(part.body,n,nxt,n)
  d.update(kind='branch',expr=part.expr,next=[body,nxt])
  if op==h.cit_do:return body
 elif op==h.cit_for:
  part=ins.cfor
  step=audit_expr(part.step,n,ins.ea)
  body=audit_build(part.body,step,nxt,step)
  d.update(kind='branch',expr=part.expr,next=[body,nxt])
  return audit_expr(part.init,n,ins.ea)
 elif op==h.cit_goto:d.update(kind='goto',label=int(ins.cgoto.label_num))
 elif op==h.cit_break:d.update(kind='edge',next=[brk])
 elif op==h.cit_continue:d.update(kind='edge',next=[cont])
 elif op==h.cit_return:d.update(kind='return',expr=ins.creturn.expr)
 elif op==h.cit_switch:
  part=ins.cswitch
  branches=[]
  for case in part.cases:branches.append(audit_build(case,nxt,nxt,cont))
  d.update(kind='switch',expr=part.expr,next=branches or [nxt])
 else:d.update(next=[nxt],opcode=int(op))
 return n
audit_entry=audit_build(audit_cf.body,None)
for n in audit_nodes.values():
 if n['kind']=='goto':
  n['next']=[audit_labels.get(n['label'])]
print('built',len(audit_nodes),'labels',len(audit_labels),'entry',audit_entry)
print('returns',[(n['id'],hex(n['ea'])) for n in audit_nodes.values() if n['kind']=='return'])

import ida_lines
audit_track=(233,234,235,279,282,287,288,357,363,4)
audit_ix={v:i for i,v in enumerate(audit_track)}
def audit_value(e,vals):
 h=ida_hexrays
 if e is None:return None
 if e.op==h.cot_num:return int(e.numval())&((1<<(max(1,e.type.get_size())*8))-1)
 if e.op==h.cot_var:return vals[audit_ix[e.v.idx]] if e.v.idx in audit_ix else None
 if e.op==h.cot_cast:return audit_value(e.x,vals)
 if e.op in (h.cot_lnot,h.cot_neg,h.cot_bnot):
  v=audit_value(e.x,vals)
  if v is None:return None
  return int(not v) if e.op==h.cot_lnot else (-v if e.op==h.cot_neg else ~v)
 if e.op in (h.cot_eq,h.cot_ne,h.cot_sgt,h.cot_sge,h.cot_slt,h.cot_sle,h.cot_ugt,h.cot_uge,h.cot_ult,h.cot_ule,h.cot_land,h.cot_lor,h.cot_add,h.cot_sub,h.cot_band,h.cot_bor,h.cot_xor):
  a=audit_value(e.x,vals);b=audit_value(e.y,vals)
  if e.op==h.cot_land and ((a is not None and not a) or (b is not None and not b)):return 0
  if e.op==h.cot_lor and ((a is not None and a) or (b is not None and b)):return 1
  if a is None or b is None:return None
  if e.op in (h.cot_sgt,h.cot_sge,h.cot_slt,h.cot_sle):
   a=a-(1<<32) if a&0x80000000 else a
   b=b-(1<<32) if b&0x80000000 else b
  ops={h.cot_eq:lambda:a==b,h.cot_ne:lambda:a!=b,h.cot_sgt:lambda:a>b,h.cot_ugt:lambda:a>b,h.cot_sge:lambda:a>=b,h.cot_uge:lambda:a>=b,h.cot_slt:lambda:a<b,h.cot_ult:lambda:a<b,h.cot_sle:lambda:a<=b,h.cot_ule:lambda:a<=b,h.cot_land:lambda:bool(a and b),h.cot_lor:lambda:bool(a or b),h.cot_add:lambda:a+b,h.cot_sub:lambda:a-b,h.cot_band:lambda:a&b,h.cot_bor:lambda:a|b,h.cot_xor:lambda:a^b}
  return int(ops[e.op]())&0xFFFFFFFF
 return None
for n in audit_nodes.values():
 e=n['expr']
 n['text']=ida_lines.tag_remove(e.print1(audit_cf)) if e is not None else ''
 n['events']=0
 if n['kind']=='expr' and 'qmemcpy' in n['text']:
  if n['text'].startswith('qmemcpy(&wmp1_input_cbc_feedback_snapshot'):n['events']|=1
  if n['text'].startswith('qmemcpy(&wmp1_output_cbc_feedback_snapshot'):n['events']|=2
  if n['text'].startswith('qmemcpy(&dword_7FF697BBA000, &wmp1_input'):n['events']|=4
  if n['text'].startswith('qmemcpy(&dword_7FF697BBA000, &wmp1_output'):n['events']|=8
audit_queue=[(audit_entry,(None,)*len(audit_track),0)]
audit_seen=set()
audit_returns=set()
audit_unknown_state_assignments=set()
def audit_batch(limit=15000):
 processed=0
 while audit_queue and processed<limit:
  item=audit_queue.pop()
  if item in audit_seen:continue
  audit_seen.add(item);processed+=1
  nid,vals,events=item
  if nid is None:continue
  n=audit_nodes[nid];events|=n['events'];e=n['expr']
  if n['kind']=='return':
   audit_returns.add((hex(n['ea']),audit_value(e,vals),events));continue
  if n['kind']=='expr' and e.op==ida_hexrays.cot_asg and e.x.op==ida_hexrays.cot_var and e.x.v.idx in audit_ix:
   vi=e.x.v.idx;value=audit_value(e.y,vals)
   if vi==233 and value is None:audit_unknown_state_assignments.add((hex(n['ea']),n['text']))
   mutable=list(vals);mutable[audit_ix[vi]]=value;vals=tuple(mutable)
  targets=n['next']
  if n['kind']=='branch':
   value=audit_value(e,vals)
   if value is not None:targets=[targets[0] if value else targets[1]]
  for target in targets:audit_queue.append((target,vals,events))
 print('processed',processed,'seen',len(audit_seen),'queue',len(audit_queue),'returns',sorted(audit_returns,key=str),'unknown state writes',len(audit_unknown_state_assignments))
print('snapshot events',[(hex(n['ea']),n['events'],n['text']) for n in audit_nodes.values() if n['events']])
audit_batch(10000)

audit18_queue=[(audit_entry,(None,)*len(audit_track),0,0)]
audit18_seen=set()
audit18_returns=set()
audit18_continuations=set()
audit18_unknown=set()
def audit18_batch(limit=12000):
 processed=0
 while audit18_queue and processed<limit:
  item=audit18_queue.pop()
  if item in audit18_seen:continue
  audit18_seen.add(item);processed+=1
  nid,vals,events,records=item
  if nid is None:continue
  n=audit_nodes[nid];e=n['expr']
  if n['events']&4:
   records+=1
   if records>1:
    audit18_continuations.add((events,vals[audit_ix[357]]));continue
  events|=n['events']
  if n['kind']=='return':
   value=audit_value(e,vals)
   audit18_returns.add((hex(n['ea']),value,events,records))
   if value is None:audit18_unknown.add(item)
   continue
  variants=[vals]
  if n['kind']=='expr' and e.op==ida_hexrays.cot_asg and e.x.op==ida_hexrays.cot_var and e.x.v.idx in audit_ix:
   vi=e.x.v.idx;values=[audit_value(e.y,vals)]
   if vi==4 and n['ea']==0x7FF697B94180:values=[0,6,1030]
   if vi==4 and n['ea']==0x7FF697B9CAD3:values=[0,1,257]
   variants=[]
   for value in values:
    mutable=list(vals);mutable[audit_ix[vi]]=value;variants.append(tuple(mutable))
  for variant in variants:
   targets=n['next']
   if n['kind']=='switch' and n['ea']==0x7FF697B95C65:targets=[targets[18]]
   if n['kind']=='branch':
    value=audit_value(e,variant)
    if value is not None:targets=[targets[0] if value else targets[1]]
   for target in targets:audit18_queue.append((target,variant,events,records))
 print('processed',processed,'seen',len(audit18_seen),'remaining',len(audit18_queue),'returns',sorted(audit18_returns,key=str),'continuations',sorted(audit18_continuations,key=str),'unknown',len(audit18_unknown))
audit18_batch()
